import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import intersection


# ---- obviously-correct reference model (written from spec only) ----

def _ref_is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def _ref_expected(interval1, interval2) -> str:
    l = max(interval1[0], interval2[0])
    r = min(interval1[1], interval2[1])
    if r < l:
        return "NO"
    return "YES" if _ref_is_prime(r - l) else "NO"


def _length(interval1, interval2) -> int:
    return min(interval1[1], interval2[1]) - max(interval1[0], interval2[0])


valid_interval = st.tuples(
    st.integers(min_value=-50, max_value=50),
    st.integers(min_value=0, max_value=50),
).map(lambda t: (t[0], t[0] + t[1]))


# ---- spec examples ----

@pytest.mark.parametrize(
    "a,b,expected",
    [
        ((1, 2), (2, 3), "NO"),
        ((-1, 1), (0, 4), "NO"),
        ((-3, -1), (-5, 5), "YES"),
    ],
)
def test_spec_samples_match(a, b, expected):
    assert intersection(a, b) == expected


def test_docstring_example_is_not_prime():
    # (1,3) & (2,4) = (2,3), length 1, not prime
    assert intersection((1, 3), (2, 4)) == "NO"


# ---- prime / composite length behaviour ----

@pytest.mark.parametrize("length", [2, 3, 5, 7, 11, 13])
def test_prime_length_returns_YES(length):
    # intersection exactly (0, length)
    assert intersection((0, length), (0, length)) == "YES"
    assert intersection((-100, length), (0, 100)) == _ref_expected((-100, length), (0, 100))
    assert _ref_expected((0, length), (0, length)) == "YES"


@pytest.mark.parametrize("length", [0, 1, 4, 6, 8, 9, 10, 12, 14, 15, 16, 21, 25, 27, 35, 49])
def test_composite_or_small_length_returns_NO(length):
    assert _ref_expected((0, length), (0, length)) == "NO"
    assert intersection((0, length), (0, length)) == "NO"


def test_length_four_is_not_prime():
    # smallest composite > 2 that exposes range(2, sqrt) bug
    assert intersection((0, 4), (0, 4)) == "NO"


def test_length_six_is_not_prime():
    assert intersection((1, 7), (1, 7)) == "NO"


def test_length_nine_is_not_prime():
    assert intersection((0, 9), (0, 9)) == "NO"


def test_length_fifteen_is_not_prime():
    assert intersection((0, 15), (0, 15)) == "NO"


def test_length_twentyfive_is_not_prime():
    assert intersection((-5, 20), (-5, 20)) == "NO"


# ---- structural properties ----

@given(a=valid_interval, b=valid_interval)
def test_equivalence_to_reference_model(a, b):
    assert intersection(a, b) == _ref_expected(a, b)


@given(a=valid_interval, b=valid_interval)
def test_symmetry_of_arguments(a, b):
    assert intersection(a, b) == intersection(b, a)


@given(a=valid_interval, b=valid_interval)
def test_result_is_only_YES_or_NO(a, b):
    assert intersection(a, b) in ("YES", "NO")


@given(a=valid_interval, b=valid_interval)
def test_YES_implies_prime_length(a, b):
    res = intersection(a, b)
    l = _length(a, b)
    if res == "YES":
        assert l >= 0
        assert _ref_is_prime(l)


@given(a=valid_interval, b=valid_interval)
def test_disjoint_intervals_return_NO(a, b):
    assume(min(a[1], b[1]) < max(a[0], b[0]))
    assert intersection(a, b) == "NO"


@given(a=valid_interval, b=valid_interval)
def test_touching_single_point_returns_NO(a, b):
    # force single-point intersection of length 0
    assume(a[1] < b[0] or b[1] < a[0] or True)
    # construct touching pair deterministically from a
    x = a[0]
    assert intersection((x, x + 5), (x + 5, x + 10)) == "NO"


@given(a=valid_interval, b=valid_interval)
def test_length_zero_or_one_never_YES(a, b):
    assume(min(a[1], b[1]) - max(a[0], b[0]) in (0, 1))
    assert intersection(a, b) == "NO"


def test_identical_intervals_follow_primality_of_length():
    for start in [-10, -1, 0, 5]:
        for length in range(0, 20):
            iv = (start, start + length)
            assert intersection(iv, iv) == _ref_expected(iv, iv)


def test_containment_preserves_length():
    # (0,10) contains (4,6): intersection length 2 -> YES
    assert intersection((0, 10), (4, 6)) == "YES"
    # (0,10) contains (4,8): intersection length 4 -> NO
    assert intersection((0, 10), (4, 8)) == "NO"
    # (0,10) contains (1,10): length 9 -> NO
    assert intersection((0, 10), (1, 10)) == "NO"
